class _Official_groupby_GroupByMethods:
    param_names = ['dtype', 'method', 'application', 'ncols']
    params = [['int', 'int16', 'float', 'object', 'datetime', 'uint'], ['all', 'any', 'bfill', 'count', 'cumcount', 'cummax', 'cummin', 'cumprod', 'cumsum', 'describe', 'diff', 'ffill', 'first', 'head', 'last', 'max', 'min', 'median', 'mean', 'nunique', 'pct_change', 'prod', 'quantile', 'rank', 'sem', 'shift', 'size', 'skew', 'std', 'sum', 'tail', 'unique', 'value_counts', 'var'], ['direct', 'transformation'], [1, 5], ['cython', 'numba']]

    def setup(self, dtype, method, application, ncols, engine):
        if method in method_blocklist.get(dtype, {}):
            raise NotImplementedError
        if ncols != 1 and method in ['value_counts', 'unique']:
            raise NotImplementedError
        if application == 'transformation' and method in ['describe', 'head', 'tail', 'unique', 'value_counts', 'size']:
            raise NotImplementedError
        if engine == 'numba' and method in _numba_unsupported_methods or ncols > 1 or application == 'transformation' or (dtype == 'datetime'):
            raise NotImplementedError
        if method == 'describe':
            ngroups = 20
        elif method == 'skew':
            ngroups = 100
        else:
            ngroups = 1000
        size = ngroups * 2
        rng = np.arange(ngroups).reshape(-1, 1)
        rng = np.broadcast_to(rng, (len(rng), ncols))
        taker = np.random.randint(0, ngroups, size=size)
        values = rng.take(taker, axis=0)
        if dtype == 'int':
            key = np.random.randint(0, size, size=size)
        elif dtype in ('int16', 'uint'):
            key = np.random.randint(0, size, size=size, dtype=dtype)
        elif dtype == 'float':
            key = np.concatenate([np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0])
        elif dtype == 'object':
            key = ['foo'] * size
        elif dtype == 'datetime':
            key = date_range('1/1/2011', periods=size, freq='s')
        cols = [f'values{n}' for n in range(ncols)]
        df = DataFrame(values, columns=cols)
        df['key'] = key
        if len(cols) == 1:
            cols = cols[0]
        kwargs = {}
        if engine == 'numba':
            kwargs['engine'] = engine
        if application == 'transformation':
            self.as_group_method = lambda: df.groupby('key')[cols].transform(method, **kwargs)
            self.as_field_method = lambda: df.groupby(cols)['key'].transform(method, **kwargs)
        else:
            self.as_group_method = partial(getattr(df.groupby('key')[cols], method), **kwargs)
            self.as_field_method = partial(getattr(df.groupby(cols)['key'], method), **kwargs)

    def time_dtype_as_group(self, dtype, method, application, ncols, engine):
        self.as_group_method()

    def time_dtype_as_field(self, dtype, method, application, ncols, engine):
        self.as_field_method()

