class _Official_groupby_TransformEngine:
    param_names = ['parallel']
    params = [[True, False]]

    def setup(self, parallel):
        N = 10 ** 3
        data = DataFrame({0: [str(i) for i in range(100)] * N, 1: list(range(100)) * N}, columns=[0, 1])
        self.parallel = parallel
        self.grouper = data.groupby(0)

    def time_series_numba(self, parallel):

        def function(values, index):
            return values * 5
        self.grouper[1].transform(function, engine='numba', engine_kwargs={'parallel': self.parallel})

    def time_series_cython(self, parallel):

        def function(values):
            return values * 5
        self.grouper[1].transform(function, engine='cython')

    def time_dataframe_numba(self, parallel):

        def function(values, index):
            return values * 5
        self.grouper.transform(function, engine='numba', engine_kwargs={'parallel': self.parallel})

    def time_dataframe_cython(self, parallel):

        def function(values):
            return values * 5
        self.grouper.transform(function, engine='cython')

class _Official_groupby_AggEngine:
    param_names = ['parallel']
    params = [[True, False]]

    def setup(self, parallel):
        N = 10 ** 3
        data = DataFrame({0: [str(i) for i in range(100)] * N, 1: list(range(100)) * N}, columns=[0, 1])
        self.parallel = parallel
        self.grouper = data.groupby(0)

    def time_series_numba(self, parallel):

        def function(values, index):
            total = 0
            for i, value in enumerate(values):
                if i % 2:
                    total += value + 5
                else:
                    total += value * 2
            return total
        self.grouper[1].agg(function, engine='numba', engine_kwargs={'parallel': self.parallel})

    def time_series_cython(self, parallel):

        def function(values):
            total = 0
            for i, value in enumerate(values):
                if i % 2:
                    total += value + 5
                else:
                    total += value * 2
            return total
        self.grouper[1].agg(function, engine='cython')

    def time_dataframe_numba(self, parallel):

        def function(values, index):
            total = 0
            for i, value in enumerate(values):
                if i % 2:
                    total += value + 5
                else:
                    total += value * 2
            return total
        self.grouper.agg(function, engine='numba', engine_kwargs={'parallel': self.parallel})

    def time_dataframe_cython(self, parallel):

        def function(values):
            total = 0
            for i, value in enumerate(values):
                if i % 2:
                    total += value + 5
                else:
                    total += value * 2
            return total
        self.grouper.agg(function, engine='cython')

