class _Official_groupby_Resample:

    def setup(self):
        num_timedeltas = 20000
        num_groups = 3
        index = MultiIndex.from_product([np.arange(num_groups), to_timedelta(np.arange(num_timedeltas), unit='s')], names=['groups', 'timedeltas'])
